output.output:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #f7fafc;
  color: #2d3748;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

.header {
  text-align: center;
  margin-bottom: 3rem;
  border-bottom: 2px solid #e2e8f0;
  padding-bottom: 1.5rem;
}

.header h1 {
  font-size: 2.5rem;
  color: #1a202c;
}

.main-content {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 3rem;
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

.catalog-section, .cart-section {
  background-color: #ffffff;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 2rem;
}

h2 {
  font-size: 1.75rem;
  margin-bottom: 1.5rem;
  color: #2d3748;
  border-bottom: 1px solid #edf2f7;
  padding-bottom: 0.75rem;
}

.products-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.product-card {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1.5rem;
  background-color: #f8fafc;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.price {
  font-size: 1.5rem;
  font-weight: bold;
  color: #2b6cb0;
  margin-bottom: 0.5rem;
}

.inventory {
  font-size: 0.95rem;
  color: #718096;
  margin-bottom: 1rem;
}

.add-to-cart-btn {
  background-color: #3182ce;
  color: white;
  border: none;
  border-radius: 6px;
  padding: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
}

.add-to-cart-btn:hover:not(:disabled) {
  background-color: #2b6cb0;
}

.add-to-cart-btn:disabled {
  background-color: #cbd5e0;
  cursor: not-allowed;
}

.empty-cart-text {
  color: #718096;
  font-style: italic;
}

.cart-content {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.cart-items {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.cart-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #edf2f7;
  padding-bottom: 1rem;
}

.item-info h4 {
  font-size: 1.1rem;
  margin-bottom: 0.25rem;
}

.item-info p {
  color: #718096;
  font-size: 0.9rem;
}

.item-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.qty-btn {
  background-color: #edf2f7;
  border: none;
  border-radius: 4px;
  width: 2rem;
  height: 2rem;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
}

.qty-btn:hover {
  background-color: #e2e8f0;
}

.qty-display {
  font-size: 1.1rem;
  font-weight: 600;
  min-width: 1.5rem;
  text-align: center;
}

.remove-btn {
  background-color: transparent;
  color: #e53e3e;
  border: none;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 600;
  margin-left: 0.5rem;
}

.remove-btn:hover {
  text-decoration: underline;
}

.coupon-form {
  display: flex;
  gap: 0.5rem;
  margin-top: 1rem;
}

.coupon-input {
  flex: 1;
  padding: 0.75rem;
  border: 1px solid #cbd5e0;
  border-radius: 6px;
  font-size: 1rem;
}

.coupon-input:focus {
  outline: none;
  border-color: #3182ce;
  box-shadow: 0 0 0 3px rgba(66, 153, 225, 0.5);
}

.apply-coupon-btn {
  background-color: #4a5568;
  color: white;
  border: none;
  border-radius: 6px;
  padding: 0.75rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
}

.apply-coupon-btn:hover {
  background-color: #2d3748;
}

.coupon-success {
  color: #38a169;
  font-weight: 600;
  font-size: 0.95rem;
}

.coupon-error {
  color: #e53e3e;
  font-weight: 600;
  font-size: 0.95rem;
}

.order-summary {
  border-top: 2px solid #edf2f7;
  padding-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.summary-line {
  display: flex;
  justify-content: space-between;
  font-size: 1.1rem;
}

.discount-line {
  color: #38a169;
  font-weight: 600;
}

.total-line {
  font-size: 1.4rem;
  font-weight: bold;
  border-top: 1px solid #edf2f7;
  padding-top: 0.75rem;
  margin-top: 0.5rem;
}

.checkout-btn {
  background-color: #38a169;
  color: white;
  border: none;
  border-radius: 6px;
  padding: 1rem;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.2s;
  margin-top: 1rem;
}

.checkout-btn:hover:not(:disabled) {
  background-color: #2f855a;
}

.checkout-btn:disabled {
  background-color: #cbd5e0;
  cursor: not-allowed;
}

.checkout-success {
  background-color: #f0fff4;
  border: 1px solid #c6f6d5;
  color: #22543d;
  padding: 1rem;
  border-radius: 6px;
  margin-top: 1.5rem;
  font-weight: 600;
  text-align: center;
}

.checkout-error {
  background-color: #fff5f5;
  border: 1px solid #fed7d7;
  color: #742a2a;
  padding: 1rem;
  border-radius: 6px;
  margin-top: 1.5rem;
  font-weight: 600;
  text-align: center;
}

.loading, .error {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 50vh;
  font-size: 1.5rem;
  font-weight: 600;
}

.error {
  color: #e53e3e;
}
